mapper.select:
select
a.camera_id,
a.algorithm_id,
a.algorithm_name,
a.status,
a.preset_id,
a.if_del,
a.if_show,
a.pic_url,
a.apply_module,
a.create_time,
a.update_time,
b.preset_name as presetName,
d.dict_note as analysTypeName,
e.analys_type as analysType
from t_algorithm_conf a,t_camera_preset b,t_dict_business d,t_algorithm_info e
where 1 = 1 and a.preset_id = b.preset_id and d.dict_code = e.analys_type and a.algorithm_id=e.algorithm_id
 and a.camera_id = #{cameraId, jdbcType=BIGINT}
 and a.algorithm_id = #{algorithmId, jdbcType=BIGINT}
 and a.algorithm_name = #{algorithmName, jdbcType=VARCHAR}
 and a.status = #{status, jdbcType=INTEGER}
 and a.preset_id = #{presetId, jdbcType=VARCHAR}
 and a.if_del = #{ifDel, jdbcType=INTEGER}
 and a.if_show = #{ifShow, jdbcType=INTEGER}
 and a.pic_url = #{picUrl, jdbcType=VARCHAR}
 and a.apply_module = #{applyModule, jdbcType=INTEGER}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}

